//! The character classes the pre-tokenizer splits by: letters, numbers and whitespace,
//! as Unicode (and llama.cpp) define them.
//!
//! Letters and numbers come from our own tables (`unicode_tables.rs`, generated by
//! `tools/gen_unicode_tables.py`). Rust's `char::is_alphabetic` isn't the same thing:
//! it also counts combining marks such as Hindi vowel signs, which would split Hindi
//! text differently from llama.cpp. Whitespace is Unicode's White_Space property, which
//! is exactly what `char::is_whitespace` checks.

use std::cmp::Ordering;

use super::unicode_case_tables::{LOWER, UPPER};
use super::unicode_tables::{LETTERS, MARKS, NUMBERS};

pub use super::unicode_case_tables::CASE_UNICODE_VERSION;
pub use super::unicode_tables::UNICODE_VERSION;

fn in_table(table: &[(u32, u32)], c: char) -> bool {
    let cp = c as u32;
    table
        .binary_search_by(|&(first, last)| {
            if last < cp {
                Ordering::Less
            } else if first > cp {
                Ordering::Greater
            } else {
                Ordering::Equal
            }
        })
        .is_ok()
}

/// Unicode general category L.
#[inline]
pub fn is_letter(c: char) -> bool {
    if c.is_ascii() {
        c.is_ascii_alphabetic()
    } else {
        in_table(LETTERS, c)
    }
}

/// Unicode general category M (combining marks). No ASCII character is a mark.
#[inline]
pub fn is_mark(c: char) -> bool {
    !c.is_ascii() && in_table(MARKS, c)
}

/// The Llama 4 split's "upper" class, [\p{Lu}\p{Lt}\p{Lm}\p{Lo}\p{M}]: a letter that
/// isn't lowercase, or a mark.
#[inline]
pub fn is_upper_class(c: char) -> bool {
    if c.is_ascii() {
        c.is_ascii_uppercase()
    } else {
        (in_table(LETTERS, c) && !in_table(LOWER, c)) || in_table(MARKS, c)
    }
}

/// The Llama 4 split's "lower" class, [\p{Ll}\p{Lm}\p{Lo}\p{M}]: a letter that isn't
/// uppercase or titlecase, or a mark.
#[inline]
pub fn is_lower_class(c: char) -> bool {
    if c.is_ascii() {
        c.is_ascii_lowercase()
    } else {
        (in_table(LETTERS, c) && !in_table(UPPER, c)) || in_table(MARKS, c)
    }
}

/// Unicode general category N.
#[inline]
pub fn is_number(c: char) -> bool {
    if c.is_ascii() {
        c.is_ascii_digit()
    } else {
        in_table(NUMBERS, c)
    }
}

/// Unicode's White_Space property.
#[inline]
pub fn is_whitespace(c: char) -> bool {
    c.is_whitespace()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn letters() {
        for c in ['a', 'Z', 'é', 'ß', 'Ж', 'ह', '中', 'ん', 'ʰ'] {
            assert!(is_letter(c), "{c:?}");
        }
        // Combining marks (Hindi vowel sign AA, combining acute) and letter numbers
        // (Roman numeral twelve) are not letters, though Rust calls them alphabetic.
        for c in ['\u{093E}', '\u{0301}', 'Ⅻ', '1', ' ', '!', '😀'] {
            assert!(!is_letter(c), "{c:?}");
        }
        assert!('\u{093E}'.is_alphabetic(), "the reason for our own table");
    }

    #[test]
    fn numbers() {
        for c in ['0', '9', '٣', '५', 'Ⅻ', '½', '²'] {
            assert!(is_number(c), "{c:?}");
        }
        for c in ['a', ' ', '-', '.'] {
            assert!(!is_number(c), "{c:?}");
        }
    }

    #[test]
    fn whitespace() {
        for c in [
            ' ', '\t', '\n', '\r', '\u{0B}', '\u{0C}', '\u{85}', '\u{A0}', '\u{3000}', '\u{2028}',
        ] {
            assert!(is_whitespace(c), "{c:?}");
        }
        // Zero-width space and the file separator are not White_Space.
        for c in ['\u{200B}', '\u{1C}', 'a'] {
            assert!(!is_whitespace(c), "{c:?}");
        }
    }

    #[test]
    fn tables_are_sorted_and_disjoint() {
        for table in [LETTERS, MARKS, NUMBERS] {
            for pair in table.windows(2) {
                assert!(pair[0].0 <= pair[0].1 && pair[0].1 < pair[1].0, "{pair:?}");
            }
        }
    }
}
